const UpdateQuizSession = `-- name: UpdateQuizSession :one
UPDATE quiz_sessions
SET
    name = COALESCE($1::text, name),
    open_at = $2::timestamptz,
    lock_at = $3::timestamptz,
    finish_at = $4::timestamptz,
    updated_at = now()
WHERE id = $5::text
RETURNING id, quiz_id, name, state, open_at, lock_at, finish_at, created_by, created_at, updated_at
`

type UpdateQuizSessionParams struct {
	Name     *string            `json:"name"`
	Openat   pgtype.Timestamptz `json:"openat"`
	Lockat   pgtype.Timestamptz `json:"lockat"`
	Finishat pgtype.Timestamptz `json:"finishat"`
	ID       string             `json:"id"`
}

func (q *Queries) UpdateQuizSession(ctx context.Context, arg UpdateQuizSessionParams) (*QuizSession, error) {
	row := q.db.QueryRow(ctx, UpdateQuizSession,
		arg.Name,
		arg.Openat,
		arg.Lockat,
		arg.Finishat,
		arg.ID,
	)
	var i QuizSession
	err := row.Scan(
		&i.ID,
		&i.QuizID,
		&i.Name,
		&i.State,
		&i.OpenAt,
		&i.LockAt,
		&i.FinishAt,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return &i, err
}

const UpdateQuizSessionState = `-- name: UpdateQuizSessionState :one
UPDATE quiz_sessions
SET
    state = $1::text,
    open_at = CASE WHEN $1::text = 'OPEN' AND open_at IS NULL THEN now() ELSE open_at END,
    lock_at = CASE WHEN $1::text = 'LOCKED' AND lock_at IS NULL THEN now() ELSE lock_at END,
    finish_at = CASE WHEN $1::text = 'FINISHED' AND finish_at IS NULL THEN now() ELSE finish_at END,
    updated_at = now()
WHERE id = $2::text
RETURNING id, quiz_id, name, state, open_at, lock_at, finish_at, created_by, created_at, updated_at
`

type UpdateQuizSessionStateParams struct {
	State string `json:"state"`
	ID    string `json:"id"`
}

func (q *Queries) UpdateQuizSessionState(ctx context.Context, arg UpdateQuizSessionStateParams) (*QuizSession, error) {
	row := q.db.QueryRow(ctx, UpdateQuizSessionState, arg.State, arg.ID)
	var i QuizSession
	err := row.Scan(
		&i.ID,
		&i.QuizID,
		&i.Name,
		&i.State,
		&i.OpenAt,
		&i.LockAt,
		&i.FinishAt,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return &i, err
}

